contract InvMutTest {
    C c;
    address initialOwner;

    constructor(C _c) {
        c = _c;
        initialOwner = c.owner();
    }

    function run(bool callRenounce, bool callTransfer, address newOwner) public payable {
        address before = initialOwner;
        if (callRenounce) {
            renounceOwnership();
        } else if (callTransfer && newOwner != address(0)) {
            transferOwnership(newOwner);
        }
        address observed = c.owner();
        address observedAgain = c.owner();
        assert(observed == observedAgain);
    }

    function renounceOwnership() internal {
        c.renounceOwnership();
    }

    function transferOwnership(address newOwner) internal {
        c.transferOwnership(newOwner);
    }

    receive() external payable {}
}

