contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address newOwner) public {
        address ownerBefore = c.owner();
        bool callerIsOwner = ownerBefore == address(this);
        bool isZero = newOwner == address(0);

        bool reverted;
        try c.transferOwnership(newOwner) {
            reverted = false;
        } catch {
            reverted = true;
        }

        address ownerAfter = c.owner();

        if (!callerIsOwner || isZero) {
            assert(reverted && ownerAfter == ownerBefore);
        } else {
            assert(!reverted && ownerAfter == newOwner);
        }
    }
}

