contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    receive() external payable {}

    function run(uint256 stakeAmount, uint256 withdrawAmount) public payable {
        require(stakeAmount > 0);
        require(withdrawAmount > 0);

        c.stake{value: 0}(stakeAmount);
        uint256 afterStake = c.totalSupply();
        uint256 balAfterStake = address(c).balance;

        c.withdraw(withdrawAmount, false);
        uint256 afterWithdraw = c.totalSupply();
        uint256 balAfterWithdraw = address(c).balance;

        assert(afterStake >= stakeAmount);
        assert(afterWithdraw == afterStake - withdrawAmount);
        assert(balAfterWithdraw == balAfterStake);
    }
}

