        uint256 tokenLastUpdateTime;
        uint256 tokenPeriodFinish;
        uint256 tokenCount;
        if (!firstReverted) {
            tokenLastUpdateTime = c.rewardData(token).lastUpdateTime;
            tokenPeriodFinish = c.rewardData(token).periodFinish;
            tokenCount = c.rewardTokens(0);
