contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address account, address rewardToken) public {
        c.addReward(rewardToken);

        uint256 balance = c.balanceOf(account);
        uint256 rewardPerToken = c.rewardPerToken(rewardToken);
        uint256 paid = c.userRewardPerTokenPaid(account, rewardToken);
        uint256 claimable = c.claimableRewards(account, rewardToken);

        uint256 earned;
        try c.earned(account, rewardToken) returns (uint256 v) {
            earned = v;
            uint256 expected = claimable + (balance * (rewardPerToken - paid)) / 1e18;
            assert(earned == expected);
        } catch {
            assert(false);
        }
    }
}

