    function run(address oldStaking, uint256 amount) public payable {
        require(true);

        // Set the migrator to this test contract so we can explore the migrator path.
        c.setMigrator(address(this));

        bool oldIsContract = oldStaking.code.length > 0;

        uint256 totalBefore = c.totalSupply();
        uint256 balBefore = c.balanceOf(address(this));

        bool reverted;
        try c.migrateStake(oldStaking, amount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // When the caller is the migrator, migrateStake must revert iff the target
        // is not a contract that can process migrateWithdraw(msg.sender, amount).
        // On success it must increase this contract's stake and the total supply by amount.
        // For all inputs, success implies the old staking address was a contract and the
        // tracked total supply increased by exactly the migrated amount.
        assert(
            reverted ||
            (
                oldIsContract &&
                amount > 0 &&
                c.totalSupply() == totalBefore + amount &&
                c.balanceOf(address(this)) == balBefore + amount
            )
        );
    }

    receive() external payable {}
}

