contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address account, uint256 amount1, uint256 amount2) public {
        // The staking token must let this contract transferFrom, which requires
        // this contract to hold enough of it. Since we cannot mint the token here,
        // the only way this test contract can drive meaningful positive-balance
        // states for `account` is if it already owns the deployed staking token.
        // We read the balance via c.balanceOf only; the token is provided by the
        // environment. To keep the rule universally quantifiable we only require
        // that amount1/amount2 are positive, and if the test contract lacks the
        // staking tokens the stake call will revert and the balance must be 0.

        uint256 beforeBalance = c.balanceOf(account);

        bool reverted1;
        if (amount1 > 0) {
            try c.stakeFor(account, amount1) { reverted1 = false; } catch { reverted1 = true; }
        } else {
            reverted1 = true;
        }

        uint256 afterFirst = c.balanceOf(account);

        bool reverted2;
        if (amount2 > 0) {
            try c.stakeFor(account, amount2) { reverted2 = false; } catch { reverted2 = true; }
        } else {
            reverted2 = true;
        }

        uint256 afterSecond = c.balanceOf(account);

        // General rule: when a stakeFor call does NOT revert, balanceOf must have
        // increased by exactly the staked amount; when it reverts, balanceOf must
        // be unchanged. This must hold across two successive calls.
        assert(
            (reverted1 ? afterFirst == beforeBalance : afterFirst == beforeBalance + amount1) &&
            (reverted2 ? afterSecond == afterFirst : afterSecond == afterFirst + amount2)
        );
    }
}

