contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address caller, address oldStaking, uint256 amount) public {
        // Determine whether the given caller is the authorized migrator.
        bool isMigrator = (caller == c.migrator());

        // Compute the stake returned by the external call that migrateStake would make:
        // if migrateStake proceeds, it first calls C(oldStaking).migrateWithdraw(caller, amount),
        // which in turn calls _withdrawFor(caller, msg.sender, amount, true, caller).
        // That reverts when amount == 0 ("Cannot withdraw 0") or when
        // c.balanceOf(caller) < amount ("Not enough staked tokens").
        uint256 callerBalance = c.balanceOf(caller);
        bool migrationWithdrawWouldSucceed = (amount > 0 && callerBalance >= amount);

        // Spec: only the migrator may call migrateStake, and the migrated amount
        // must be withdrawable from the old staking contract.
        bool expectedSuccess = isMigrator && migrationWithdrawWouldSucceed;

        // Impersonate the caller by setting msg.sender via a low-level call origin trick is not possible;
        // we instead test the general rule by checking whether 
        // calling through this test contract (msg.sender = address(this)) with caller != address(this)
        // behaves correctly. Since the test contract cannot change msg.sender for arbitrary callers,
        // we directly assert the contract's guard against non-migrator callers when the caller
        // is not this contract: such a call must be rejected.
        //
        // To make a single top-level call, use a subcall through a helper? No helpers allowed.
        // Instead, we exercise the rule only when caller == address(this):
        // in that case msg.sender on c is the test contract, so the guard checks against c.migrator().
        require(caller == address(this), "caller must be this test contract");

        // Set up the migrator address to be the test contract when testing success,
        // or a different address when testing failure.
        // The only parameters that matter are oldStaking and amount.
        // Since the test contract is the deployer/owner of a fresh c, it can set the migrator.
        address other = address(uint160(uint160(address(this)) ^ 1));
        if (expectedSuccess) {
            c.setMigrator(address(this));
        } else {
            c.setMigrator(other);
        }

        bool reverted;
        try c.migrateStake(oldStaking, amount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // General rule: migrateStake must succeed exactly when the caller is the migrator
        // and the requested amount can be withdrawn from the old staking contract.
        assert(reverted == !expectedSuccess);
    }
}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address oldStaking, uint256 amount) public {
        // The test contract is the owner/deployer; make itself the migrator so the
        // only remaining reasons for migrateStake to revert are the amount guards.
        c.setMigrator(address(this));

        uint256 beforeBalance = c.balanceOf(address(this));
        uint256 beforeSupply = c.totalSupply();

        bool reverted;
        try c.migrateStake(oldStaking, amount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // When the amount is zero, migrateWithdraw on the old contract reverts with
        // "Cannot withdraw 0", so migrateStake must revert and the balance/supply
        // must be unchanged.
        if (amount == 0) {
            assert(reverted && c.balanceOf(address(this)) == beforeBalance && c.totalSupply() == beforeSupply);
        } else {
            // For a non-zero amount the deciding factor is whether the old staking
            // contract can withdraw that amount. If it reverts for any reason, the
            // whole migrateStake must revert; if it succeeds, the stake is added.
            if (reverted) {
                assert(c.balanceOf(address(this)) == beforeBalance && c.totalSupply() == beforeSupply);
            } else {
                assert(c.balanceOf(address(this)) == beforeBalance + amount && c.totalSupply() == beforeSupply + amount);
            }
        }
    }
}

