contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address staker, address caller, uint256 amount) public {
        // Try setting staker as migrator so we can observe the non-reverting path.
        // setup: make the test contract the owner? owner is the deployer (this contract), so
        // we can call setMigrator for the staker. If _c is fresh, owner == address(this).
        c.setMigrator(staker);

        require(address(this) != caller, "");

        // before balance of staker, read via public getter
        uint256 balanceBefore = c.balanceOf(staker);

        // deciding call: caller attempts migrateWithdraw(staker, amount)
        // We cannot change msg.sender here, so caller must equal the migrator (staker) for success.
        bool reverted;
        if (caller == staker) {
            try c.migrateWithdraw(staker, amount) { reverted = false; } catch { reverted = true; }
        } else {
            try c.migrateWithdraw(staker, amount) { reverted = false; } catch { reverted = true; }
        }

        uint256 balanceAfter = c.balanceOf(staker);

        if (caller != staker) {
            assert(reverted);
        } else {
            if (amount == 0 || balanceBefore < amount) {
                assert(reverted);
            } else {
                assert(!reverted);
                assert(balanceAfter + amount == balanceBefore);
            }
        }
    }
}

