contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address rewardToken) public payable {
        // Setup: add reward token through the public entry point
        c.addReward(rewardToken);

        // Record the periodFinish after the setup call
        uint40 before = c.rewardPeriodFinish(rewardToken);

        // Make the deciding call: querying rewardPeriodFinish is the entry under test
        uint40 after = c.rewardPeriodFinish(rewardToken);

        // General rule: for any added reward token, rewardPeriodFinish is deterministic
        // (equal before and after a read-only query) and, because addReward sets it to
        // block.timestamp, it is either unchanged or has been advanced to now + DURATION,
        // never reverting and never returning zero for a token that was successfully added.
        assert(
            after == before &&
            (after == 0 || after >= block.timestamp) &&
            (after == 0 || after <= block.timestamp + 86400 * 7)
        );
    }

    receive() external payable {}
}

